import{_ as i,C as a,o as l,c as h,a2 as o,E as r,j as s,a as n}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Delivery","description":"","frontmatter":{"title":"Delivery"},"headers":[],"relativePath":"en/guide/release.md","filePath":"en/guide/release.md"}'),d={name:"en/guide/release.md"};function g(c,e,p,u,f,y){const t=a("Capture");return l(),h("div",null,[e[0]||(e[0]=o('<h1 id="delivery" tabindex="-1">Delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Delivery&quot;">​</a></h1><p>This screen tracks and delivers the project&#39;s versions: that of a module (recommended) or that of the whole project. Its first job is to <strong>show where the delivery stands</strong>; the agent and the scripts deliver, the screen shows you the state and lets you act.</p><h2 id="the-four-tabs" tabindex="-1">The four tabs <a class="header-anchor" href="#the-four-tabs" aria-label="Permalink to &quot;The four tabs&quot;">​</a></h2><p>At the top of the screen, four tabs. The chosen tab is kept for this project.</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Tracking</strong> (open by default)</td><td>The delivery in progress, or the last one: its step timeline, the state of each channel, the CI, and its notes.</td></tr><tr><td><strong>Deliver</strong></td><td>The choice of target, channel and increment, the plan, then <strong>Run…</strong> or <strong>Publish…</strong>.</td></tr><tr><td><strong>Settings</strong></td><td>Each module&#39;s build command and artifacts, and the internal and public release repositories.</td></tr><tr><td><strong>History</strong></td><td>Every delivery run, with its channel, target, tag and outcome.</td></tr></tbody></table><h2 id="tracking" tabindex="-1">Tracking <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;Tracking&quot;">​</a></h2><p>Without a delivery, the tab says &quot;No delivery yet&quot; and offers <strong>Open the delivery</strong>: you open a delivery before writing its version numbers, and it is the one that carries the delivery commits.</p><p>With a delivery, you see:</p><ul><li>at the top, its reference, its state (<strong>in progress</strong>, <strong>delivered</strong>, <strong>abandoned</strong> or <strong>removed</strong>) and its opening date; on the right, the date of the last check and the <strong>Refresh</strong> button, which reads GitHub again;</li><li>a five-step timeline — <strong>Open</strong>, <strong>Notes</strong>, <strong>Internal</strong>, <strong>Public</strong>, <strong>Closed</strong> — marked done (✓), failing (✕), to come (○) or not applicable (–). A failing step says why: &quot;missing: …&quot; for an absent platform, &quot;CI failed&quot;, &quot;not latest&quot;, &quot;to write&quot; for missing notes;</li><li>the detail per channel: the repository, the release <strong>present</strong> or <strong>absent</strong>, <strong>latest</strong> or not, the number of files and the missing platforms; under internal, the tag&#39;s <strong>CI</strong> runs, each with its link;</li><li>the path of its <strong>Notes</strong> file; for a delivery in progress, its content too: the commits since the previous tag, the epics and stories, what is new and what is fixed;</li><li><strong>Old public releases</strong>: the previous public versions still in place. <strong>Remove…</strong> removes one; type its tag to confirm.</li></ul><p>At the bottom, a delivery in progress is closed with <strong>Finish</strong> or <strong>Abandon</strong>; a closed delivery offers <strong>Open the delivery</strong> for the next one. An open delivery reads its tracking again by itself when shown.</p>',10)),r(t,{name:"release-suivi",alt:"The Tracking tab: a delivery's step timeline and the state of its channels"}),e[1]||(e[1]=s("h2",{id:"deliver",tabindex:"-1"},[n("Deliver "),s("a",{class:"header-anchor",href:"#deliver","aria-label":'Permalink to "Deliver"'},"​")],-1)),e[2]||(e[2]=s("p",null,[n("The "),s("strong",null,"Deliver"),n(" tab chooses what to deliver; the plan is computed right away, then you run it after a summary.")],-1)),r(t,{name:"release",alt:"The Deliver tab: target choice, channel, increment type and delivery plan"}),e[3]||(e[3]=o('<h3 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h3><ul><li><strong>What to deliver?</strong> First, under <strong>Modules — recommended</strong>, the project&#39;s modules with their version. Below, <strong>Whole project</strong>. The first module is selected by default.</li><li><strong>Channel</strong>: <strong>Internal</strong> or <strong>Public</strong>.</li><li><strong>Increment type</strong>: <strong>Patch</strong>, <strong>Minor</strong> or <strong>Major</strong>.</li><li>The plan of the chosen target: <ul><li>the current and target versions, for instance <code>1.4.0 → 1.4.1</code>;</li><li>the <strong>Tag</strong> that will be set, the <strong>Last tag</strong>, the <strong>Repository</strong> (the module&#39;s own, or the project&#39;s), the <strong>Release repository</strong>, the <strong>Branch</strong> and the <strong>Version files</strong>;</li><li><strong>Good to know</strong>: what to know before running, for instance a target version behind the last tag;</li><li>the <strong>Plan steps</strong>, each with its checkbox.</li></ul></li></ul><h3 id="choose-what-to-deliver" tabindex="-1">Choose what to deliver <a class="header-anchor" href="#choose-what-to-deliver" aria-label="Permalink to &quot;Choose what to deliver&quot;">​</a></h3><p>Click a module, or <strong>Whole project</strong>. The plan is recomputed at once, without writing anything.</p><p>What changes with the target:</p><table tabindex="0"><thead><tr><th>Target</th><th>Version read from</th><th>Tag set</th><th>Git acts in</th></tr></thead><tbody><tr><td>Module with its own repository</td><td>its files (<code>package.json</code>, <code>Cargo.toml</code>…)</td><td><code>v1.4.1</code></td><td>its repository</td></tr><tr><td>Module in the project repository</td><td>its files</td><td><code>site-v1.4.1</code></td><td>the project repository, bounded to the module&#39;s path</td></tr><tr><td>Whole project</td><td><code>effortless.json</code> and the declared version files</td><td><code>v0.2.0</code></td><td>the project repository</td></tr></tbody></table><p>A module&#39;s version files are detected. To impose others, declare them in <code>stacks[].release.version_files</code> of <code>effortless.json</code>.</p><h3 id="choose-the-steps" tabindex="-1">Choose the steps <a class="header-anchor" href="#choose-the-steps" aria-label="Permalink to &quot;Choose the steps&quot;">​</a></h3><p>Check the steps to run: <strong>Bump the version</strong>, <strong>Commit and push</strong>, <strong>Tag and GitHub release</strong>, <strong>Update the documentation</strong>, <strong>Build and upload the artifacts</strong>. A step that does not apply to the target is greyed out. Your choices are remembered for this project; with nothing checked, the screen asks &quot;Check at least one step.&quot;</p><h3 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h3><ol><li>Click <strong>Run…</strong>. A panel sums up the target, version, tag, repository and steps.</li><li>Read it: these actions are real (version files written, commit, push, tag, GitHub release, build) and cannot be undone with a click.</li><li>Click <strong>Confirm and run</strong>.</li></ol>',11)),r(t,{name:"release-recap",alt:"The summary before running: target, version, tag, repository, branch and steps"}),e[4]||(e[4]=o('<p>The result shows step by step: <strong>done</strong>, <strong>to do by hand</strong> (the engine could not act and says why, for instance without <code>gh</code>), <strong>failed</strong>, or <strong>not run</strong> (an earlier step failed: the chain stops).</p><p>In semi-auto work mode, the run is refused and the panel says so.</p><p>A tag is never set on uncommitted files: without <strong>Commit and push</strong>, the new version would not be in the tagged commit. The step then fails and says so.</p><h3 id="deliver-internally-or-publicly" tabindex="-1">Deliver internally or publicly <a class="header-anchor" href="#deliver-internally-or-publicly" aria-label="Permalink to &quot;Deliver internally or publicly&quot;">​</a></h3><p>Under the target, choose the <strong>Channel</strong>:</p><ul><li><strong>Internal</strong>: the delivery described above. The release and its artifacts go to the internal <strong>Release repository</strong> (by default, the code&#39;s origin repository).</li><li><strong>Public</strong>: you publish a version <strong>already delivered internally</strong>, without rebuilding it — same tag, no new bump. Only the public edition&#39;s files go out: a file marked with another edition (<code>pro</code>) stays internal, the update feed gets public addresses, and the notes are those of the version&#39;s notes file. The screen only offers versions delivered internally and not yet public. If no public repository is declared for the target, it says so and points to the <strong>Settings</strong> tab.</li></ul><p>To publish:</p><ol><li>Click <strong>Publish…</strong> next to the version.</li><li>The panel recalls the tag, the repository it comes from and the one it goes to. Publishing is public and irreversible.</li><li>Type the tag in the <strong>Type … to confirm</strong> field: the <strong>Publish</strong> button only enables then.</li></ol><p>The engine refuses, and says so, if the release does not exist on the internal channel, if it is already public, or in semi-auto mode.</p>',9)),r(t,{name:"release-public",alt:"The Public channel: internally delivered versions, ready to publish"}),e[5]||(e[5]=o('<h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ol><li>Click a module in <strong>Configured stacks</strong> to prefill the form, or enter its name in <strong>Stack</strong>.</li><li>Enter the <strong>Build command</strong>, for instance <code>pnpm build</code>. For a module, it runs in its directory.</li><li>List the <strong>Artifacts</strong>, for instance <code>dist/*.zip</code>. Leaving this field empty keeps those already saved.</li><li>Click <strong>Save the delivery</strong>.</li></ol><p>Below this form, <strong>Delivery channels</strong> sets the target&#39;s two release repositories: <strong>Internal release repository</strong> (<code>owner/name</code>; empty = the origin repository) and <strong>Public release repository</strong> (<code>owner/name</code>; empty = no public delivery). Click <strong>Save the channels</strong>.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>The <strong>History</strong> tab lists every delivery run, with its columns <strong>Date</strong>, <strong>Channel</strong> (internal or public), <strong>Target</strong>, <strong>Tag</strong> (linking to the release when it exists), <strong>Repository</strong> and <strong>Outcome</strong> (<strong>in progress</strong>, <strong>delivered</strong>, <strong>stopped</strong> or <strong>removed</strong>). It lives in <code>.effortless/deliveries.json</code>, versioned with the project.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent does the same through <code>effortless_release_plan</code> (the plan) and <code>effortless_release_apply</code> (the run, after your consent). Both take <code>stack</code> to target a module. It configures delivery through <code>effortless_release_delivery_set</code> and the channels through <code>effortless_release_channels_set</code>. It publishes through <code>effortless_release_promote</code>, which requires repeating the tag in <code>confirm</code> — after your explicit consent. It reads the history through <code>effortless_deliveries</code>.</p>',7))])}const v=i(d,[["render",g]]);export{b as __pageData,v as default};
